#include <stdio.h>
#include <string.h>
void countingSort(int arr[], int n) {
    int max=arr[0]; for(int i=1;i<n;i++) if(arr[i]>max)max=arr[i];
    int count[max+1]; memset(count,0,sizeof(count));
    for(int i=0;i<n;i++) count[arr[i]]++;
    for(int i=1;i<=max;i++) count[i]+=count[i-1];
    int out[n];
    for(int i=n-1;i>=0;i--) out[--count[arr[i]]]=arr[i];
    for(int i=0;i<n;i++) arr[i]=out[i];
}
int main(){int a[]={4,2,2,8,3,3,1};countingSort(a,7);for(int i=0;i<7;i++)printf("%d ",a[i]);return 0;}

